import copy
from ledger import transfer
from validation import validate_amount
for amount in (True, False, 0, -1, 1.0, '1', None):
    try: validate_amount(amount)
    except ValueError: pass
    else: raise AssertionError(('invalid amount accepted', amount))
for amount in (1, 10**30 + 1): validate_amount(amount)
initial = {'alice': 1000, 'bob': 200, 'eve': 0}
for source, target, amount, key in [('alice','alice',1,'x'),('missing','bob',1,'x'),
        ('alice','missing',1,'x'),('alice','bob',1001,'x'),('alice','bob',0,'x'),
        ('alice','bob',True,'x'),('alice','bob',1,''),('alice','bob',1,None)]:
    balances, receipts = dict(initial), {}
    before = copy.deepcopy((balances, receipts))
    try: transfer(balances, receipts, source, target, amount, key)
    except ValueError: pass
    else: raise AssertionError('invalid transfer accepted')
    assert (balances, receipts) == before, 'failed transfer mutated state'
balances, receipts = dict(initial), {}
receipt = transfer(balances, receipts, 'alice', 'bob', 900, 'first')
assert receipt == {'source':'alice', 'target':'bob', 'amount':900}
assert balances == {'alice':100, 'bob':1100, 'eve':0}
receipt['amount'] = 1
assert receipts['first']['amount'] == 900, 'returned receipt aliases storage'
second = transfer(balances, receipts, 'alice', 'bob', 900, 'first')
second['source'] = 'eve'
assert receipts['first']['source'] == 'alice'
assert balances == {'alice':100, 'bob':1100, 'eve':0}
for source, target, amount in [('bob','alice',900),('alice','eve',900),('alice','bob',899)]:
    before = copy.deepcopy((balances, receipts))
    try: transfer(balances, receipts, source, target, amount, 'first')
    except ValueError: pass
    else: raise AssertionError('conflicting replay accepted')
    assert (balances, receipts) == before
large = 10**30 + 1
balances, receipts = {'alice':large, 'bob':0}, {}
transfer(balances, receipts, 'alice', 'bob', large, 'large')
assert balances == {'alice':0, 'bob':large}
assert type(balances['bob']) is int
for index in range(50):
    transfer(balances, receipts, 'bob', 'alice', 1, 'r'+str(index))
assert balances == {'alice':50, 'bob':large-50}
assert sum(balances.values()) == large
print('PASS')

