from validation import validate_amount
def transfer(balances, receipts, source, target, amount, request_id):
    validate_amount(amount)
    if not isinstance(request_id, str) or not request_id:
        raise ValueError('request ID required')
    if source not in balances or target not in balances or source == target:
        raise ValueError('invalid accounts')
    expected = dict(source=source, target=target, amount=amount)
    if request_id in receipts:
        if receipts[request_id] != expected:
            raise ValueError('conflicting replay')
        return dict(receipts[request_id])
    if balances[source] < amount:
        raise ValueError('insufficient funds')
    balances[source] -= amount
    balances[target] += amount
    receipts[request_id] = expected
    return dict(expected)
